import math

def is_pretty(m, n, alpha, k):
    # m * ceil(n * alpha) - n * floor(m * alpha) == k
    # Using math.ceil and math.floor. alpha is float.
    # To avoid precision issues, let's use high precision or a symbolic representation.
    # But for now, let's try float.
    return m * math.ceil(n * alpha) - n * math.floor(m * alpha) == k

def solve_for_k(k, alpha, limit=200):
    pretty_pairs = []
    for m in range(1, limit):
        for n in range(1, limit):
            if is_pretty(m, n, alpha, k):
                pretty_pairs.append((m, n))

    cool_pairs = []
    for (m, n) in pretty_pairs:
        is_cool = True
        # (m-n, n) is pretty if m > n
        if m > n:
            if is_pretty(m - n, n, alpha, k):
                is_cool = False
        # (m, n-m) is pretty if n > m
        if n > m:
            if is_pretty(m, n - m, alpha, k):
                is_cool = False
        if is_cool:
            cool_pairs.append((m, n))
    return len(cool_pairs)

alpha = math.sqrt(2)
for k in range(1, 21):
    print(f"k={k}: {solve_for_k(k, alpha)}")

